import { InlineBadge, type InlineBadgeProps } from "@components/inline-badge";
import { clsx } from "clsx";

import { MainNavMenuClasses } from "../main-nav-menu.styles";
import { useMainNavMenu } from "../hooks/use-main-nav-menu";

export const MainNavMenuInlineBadge = ({ children, className, ...props }: InlineBadgeProps) => {
  const context = useMainNavMenu();
  const contextStyleSlots = context?.styleSlots;

  return (
    <InlineBadge
      className={clsx(MainNavMenuClasses.itemInlineBadge, className)}
      size="sm"
      styleSlots={{
        root: {
          ...contextStyleSlots?.itemInlineBadge,
        },
      }}
      variant="newInverse"
      {...props}
    >
      {children}
    </InlineBadge>
  );
};

MainNavMenuInlineBadge.displayName = "MainNavMenu.InlineBadge";
